/*
 * prog44_miller_rabin – reproduced from the obfuscated binary
 *
 * Behaviour (as observed from the original executable):
 *
 *   * No command‑line argument          → prints "NO_INPUT"
 *   * Argument cannot be parsed as a
 *     base‑10 integer (or contains extra
 *     characters)                     → prints "BAD_INPUT"
 *   * Parsed value > 0xBFA17DC6        → prints "OUT_OF_RANGE"
 *   * Value < 2                         → prints "NOT_PRIME"
 *   * Otherwise the value is tested for
 *     primality with a deterministic
 *     Miller–Rabin test using the bases
 *     {2,3,5,7,11,13}.  If the test passes
 *     the program prints "PRIME", otherwise
 *     it prints "NOT_PRIME".
 *
 * The program is deliberately small and uses only
 * standard C library facilities.  All arithmetic is
 * performed with 64‑bit unsigned integers; intermediate
 * products are computed with __int128 to avoid overflow.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

#define MAX_ALLOWED 0xBFA17DC6ULL   /* limit used by the original binary */

/* 64‑bit modular multiplication (avoids overflow by using __int128) */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    __int128 prod = ( __int128 ) a * b;
    return (uint64_t)(prod % mod);
}

/* binary modular exponentiation */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1 % mod;
    base %= mod;

    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Deterministic Miller–Rabin for 64‑bit numbers using the bases
 * 2, 3, 5, 7, 11, 13.  This matches the set used by the original program. */
static int is_prime(uint64_t n)
{
    static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    uint64_t d = n - 1;
    unsigned int s = 0;

    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a % n == 0)
            continue;               // a is a multiple of n, treat as pass

        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;

        int composite = 1;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }
        if (composite)
            return 0;               // definitely composite
    }
    return 1;                       // prime for this deterministic set
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long signed_val = strtoll(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    uint64_t n = (uint64_t)signed_val;

    if (n > MAX_ALLOWED) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (n < 2) {
        puts("NOT_PRIME");
        return 0;
    }

    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
